                        .text_style(theme::h1())
                        .family(egui::FontFamily::Monospace),
                );
                ui.label(theme::meta_text(
                    ui,
                    format!("Key {}", short_hash(&identity.spki_sha256)),
                ));
                if !address.is_empty() {
